using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class ShardResult
{
    public double lo { get; set; }
    public double hi { get; set; }
    public double mid { get; set; }
    public long count { get; set; }
}

public class FinalResult
{
    public double lo { get; set; }
    public double hi { get; set; }
    public double mid { get; set; }
    public long totalCount { get; set; }
    public double final { get; set; }
    public string final17 { get; set; }
    public string finalRoundTrip { get; set; }
}

public static class Common
{
    public const long M = 16777216L;
    public const long K = 5000000L;

    public static double Value(ulong i)
    {
        unchecked
        {
            ulong z = i * 0x9E3779B97F4A7C15UL;
            z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9UL;
            z = (z ^ (z >> 27)) * 0x94D049BB133111EBUL;
            z = z ^ (z >> 31);
            return (double)(z % 2147483647UL) / 2147483647.0;
        }
    }

    public static long CountLeqShard(int workerIndex, int totalWorkers, double mid)
    {
        long c = 0;
        for (long i = workerIndex; i < M; i += totalWorkers)
        {
            if (Value((ulong)(i + 1)) <= mid) c++;
        }
        return c;
    }

    public static string Sig17(double v)
    {
        if (v == 0.0) return "0";
        bool neg = v < 0.0;
        double a = neg ? -v : v;
        string s = a.ToString("E16", CultureInfo.InvariantCulture); // d.dddddddddddddddE+xxx (17 significant digits)
        int ePos = s.IndexOf('E');
        string mant = s.Substring(0, ePos);
        int exp = int.Parse(s.Substring(ePos + 1), CultureInfo.InvariantCulture);
        string digits = mant.Replace(".", "");
        int pointPos = exp + 1; // digits before the decimal point
        string body;
        if (pointPos <= 0) body = "0." + new string('0', -pointPos) + digits;
        else if (pointPos >= digits.Length) body = digits + new string('0', pointPos - digits.Length);
        else body = digits.Substring(0, pointPos) + "." + digits.Substring(pointPos);
        return (neg ? "-" : "") + body;
    }
}

public class Step1 : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        double lo = 0.0, hi = 1.0;
        double mid = (lo + hi) / 2.0;
        long c = Common.CountLeqShard(input.WorkerIndex, input.TotalWorkers, mid);
        var r = new ShardResult { lo = lo, hi = hi, mid = mid, count = c };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(r)));
    }
}

public class Step2 : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        var prev = input.GetPreviousOutputs(0);
        long total = 0;
        double lo = 0.0, hi = 1.0, mid = 0.5;
        bool got = false;
        foreach (var p in prev)
        {
            if (p == null) continue;
            var s = JsonSerializer.Deserialize<ShardResult>(p);
            if (!got) { lo = s.lo; hi = s.hi; mid = s.mid; got = true; }
            total += s.count;
        }
        if (total >= Common.K) hi = mid; else lo = mid;

        double newMid = (lo + hi) / 2.0;
        long c = Common.CountLeqShard(input.WorkerIndex, input.TotalWorkers, newMid);
        var r = new ShardResult { lo = lo, hi = hi, mid = newMid, count = c };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(r)));
    }
}

