        bool got = false;
        foreach (var p in prev)
        {
            if (p == null) continue;
            var s = JsonSerializer.Deserialize<ShardResult>(p);
            if (!got) { lo = s.lo; hi = s.hi; mid = s.mid; got = true; }
            total += s.count;
        }
        if (total >= Common.K) hi = mid; else lo = mid;

        double final = (lo + hi) / 2.0;
        var r = new FinalResult
        {
            lo = lo,
            hi = hi,
            mid = mid,
            totalCount = total,
            final = final,
            final17 = Common.Sig17(final),
            finalRoundTrip = final.ToString("R", CultureInfo.InvariantCulture)
        };
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(r)));
    }
}

